(function(root){
function renderExample(container,c,frame){const e=InkOnboarding.example(c);container.replaceChildren();container.className='guide-screen demo-frame-'+frame;const hud=document.createElement('div');hud.className='demo-hud';hud.innerHTML=`<span>WAVE 01</span><b>${frame===2?'0010':'0000'}</b><span>♥ ♥ ♡ ♡ ♡</span>`;const area=document.createElement('div');area.className='demo-arena';const target=document.createElement('div');target.className='demo-target';target.textContent=frame===2?(window.InkLang?window.InkLang.t('TARGET DOWN! +10'):'TARGET DOWN! +10'):e.target;const beast=document.createElement('div');beast.className='demo-beast';beast.innerHTML='<svg viewBox="0 0 160 140" aria-hidden="true"><use href="#ink-wisp"/></svg>';const mage=document.createElement('div');mage.className='demo-mage';mage.innerHTML='<svg viewBox="0 0 160 190" aria-hidden="true"><use href="#ink-mage"/></svg>';area.append(target,beast,mage);if(frame===2){const bolt=document.createElement('div');bolt.className='demo-bolt';bolt.textContent='✦';area.append(bolt)}const footer=document.createElement('div');footer.className='demo-input';if(c.control==='type'){const tr=k=>window.InkLang?window.InkLang.t(k):k;footer.textContent=frame===0?tr('⌨ Type the answer…'):frame===1?`⌨ ${e.answer}  |`:tr('✓ Automatic hit!');}else if(c.control==='voice'){footer.textContent=frame===0?tr('◉ Microphone ready'):frame===1?`◉ “${e.say}”`:tr('✓ Speech matched!');}if(frame===1){beast.querySelector('use').setAttribute('href','#ink-brute')}if(frame===2){beast.querySelector('use').setAttribute('href','#ink-boss');beast.querySelector('svg').setAttribute('viewBox','0 0 220 170')}container.append(hud,area,footer);}
root.InkGuideRender={renderExample};
})(window);
